'use strict';
// A small real-time game renderer: soil stays still while individual leaves grow and sway.
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');
const soilImage=new Image();soilImage.src='lettuce-stages.png';
let motionOn=!motionQuery.matches,lastFrame=0;
const particles=[];
const effects=document.createElement('div');effects.className='garden-effects';effects.setAttribute('aria-hidden','true');scene.append(effects);
const gardener=document.createElement('div');gardener.className='gardener';gardener.innerHTML='<span class="gardener-body">👩‍🌾</span><span class="gardener-word">밭을 골라 주세요</span>';gardener.setAttribute('aria-hidden','true');scene.append(gardener);
const motionButton=document.createElement('button');motionButton.className='motion-toggle';motionButton.textContent=motionOn?'움직임 켜짐':'움직임 줄임';motionButton.setAttribute('aria-pressed',String(motionOn));$('.farm-top').append(motionButton);motionButton.onclick=()=>{motionOn=!motionOn;motionButton.textContent=motionOn?'움직임 켜짐':'움직임 줄임';motionButton.setAttribute('aria-pressed',String(motionOn));scene.classList.toggle('still-garden',!motionOn)};
scene.classList.add('animated-garden');scene.classList.toggle('still-garden',!motionOn);
function gardenCanvases(){document.querySelectorAll('.plot').forEach(b=>{if(b.querySelector('canvas'))return;const canvas=document.createElement('canvas');canvas.className='living-plot';canvas.width=480;canvas.height=380;canvas.setAttribute('aria-hidden','true');b.querySelector('.sprite').replaceWith(canvas);b.style.setProperty('--plot-delay',Number(b.dataset.plot)*80+'ms')})}
function drawLeaf(ctx,x,y,size,angle,shade,phase){ctx.save();ctx.translate(x,y);ctx.rotate(angle);const bend=Math.sin(phase)*size*.045;const g=ctx.createLinearGradient(0,0,0,-size);g.addColorStop(0,'#386c1f');g.addColorStop(.5,shade);g.addColorStop(1,'#b1dd59');ctx.fillStyle=g;ctx.strokeStyle='#406d25';ctx.lineWidth=.65;ctx.beginPath();ctx.moveTo(0,0);ctx.bezierCurveTo(-size*.65,-size*.25,-size*.42,-size*.88,bend,-size);ctx.bezierCurveTo(size*.5,-size*.95,size*.63,-size*.2,0,0);ctx.fill();ctx.stroke();ctx.strokeStyle='#d8ed8c99';ctx.lineWidth=Math.max(.7,size*.022);ctx.beginPath();ctx.moveTo(0,-2);ctx.quadraticCurveTo(bend*.6,-size*.5,bend,-size*.87);ctx.stroke();for(let k=1;k<4;k++){const y=-size*k*.2;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(size*.2,y-size*.14);ctx.moveTo(0,y);ctx.lineTo(-size*.2,y-size*.12);ctx.stroke()}ctx.restore()}
function drawLettuce(ctx,x,y,growth,t,seed){ctx.save();ctx.translate(x,y);const size=5+growth*48;const sway=motionOn?Math.sin(t*1.7+seed)*(.035+growth*.015):0;ctx.rotate(sway);ctx.fillStyle='#243d1b30';ctx.beginPath();ctx.ellipse(0,2,size*.8,size*.28,0,0,Math.PI*2);ctx.fill();if(growth<.17){ctx.strokeStyle='#658b33';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-size*.8);ctx.stroke();drawLeaf(ctx,-1,-size*.6,size*.85,-.8,'#69b648',t+seed);drawLeaf(ctx,1,-size*.6,size*.9,.8,'#85c849',t+seed+2)}else{for(let i=0;i<9;i++){const a=(i/9)*Math.PI*2;const r=size*.26;drawLeaf(ctx,Math.sin(a)*r,Math.cos(a)*r*.45,size*(.7+(i%3)*.1),a*.85,['#70ac35','#8fc747','#589d30'][i%3],t+i+seed)}for(let i=0;i<5;i++){drawLeaf(ctx,0,-size*.18,size*.58,(i-2)*.65,'#9dcc46',t+i)}}ctx.restore()}
function drawPlot(canvas,p,index,now){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,480,380);const time=now/1000;const progress=p.wateredAt?Math.min(1,Math.max(0,(Date.now()-p.wateredAt)/GROW_MS)):0;canvas.dataset.growth=progress.toFixed(3);if(soilImage.complete&&soilImage.naturalWidth){ctx.save();ctx.beginPath();ctx.moveTo(236,36);ctx.lineTo(289,55);ctx.lineTo(461,181);ctx.lineTo(463,227);ctx.lineTo(271,352);ctx.lineTo(237,348);ctx.lineTo(30,223);ctx.lineTo(25,185);ctx.closePath();ctx.clip();ctx.drawImage(soilImage,0,0,soilImage.naturalWidth/3,soilImage.naturalHeight/2,0,-40,480,450);ctx.restore()}if(p.wateredAt){ctx.fillStyle='#30492418';ctx.beginPath();ctx.moveTo(70,169);ctx.lineTo(226,61);ctx.lineTo(413,189);ctx.lineTo(259,289);ctx.closePath();ctx.fill()}const spots=[[156,178],[262,122],[321,214]];if(p.seeded&&!p.wateredAt){spots.forEach(([x,y],i)=>{ctx.save();ctx.translate(x,y);ctx.rotate(-.6+i*.3);ctx.fillStyle='#f4d28b';ctx.shadowColor='#57411a';ctx.shadowBlur=4;ctx.beginPath();ctx.ellipse(0,0,7,3.5,0,0,Math.PI*2);ctx.fill();ctx.restore()})}if(p.wateredAt)spots.forEach(([x,y],i)=>drawLettuce(ctx,x,y,progress,time,index+i*2));if(progress===1&&motionOn){ctx.fillStyle='#fff8ad';for(let i=0;i<3;i++){const s=Math.max(0,Math.sin(time*2+i*2));ctx.globalAlpha=s;const x=spots[i][0]+Math.cos(time+i)*30,y=spots[i][1]-55-Math.sin(time*.8+i)*10;ctx.fillRect(x-2,y-5,4,10);ctx.fillRect(x-5,y-2,10,4)}ctx.globalAlpha=1}}
function addParticle(x,y,char,dx,dy,duration=1000,kind='burst'){if(!motionOn)return;const e=document.createElement('span');e.className='garden-particle '+kind;e.textContent=char;effects.append(e);particles.push({el:e,x,y,dx,dy,born:performance.now(),duration,kind})}
function locateInScene(el){const a=el.getBoundingClientRect(),s=scene.getBoundingClientRect();return {x:a.left-s.left+a.width*.5,y:a.top-s.top+a.height*.5}}
function animateAction(b,stage){const pos=locateInScene(b),target=locateInScene($('.farm-basket'));gardener.style.left=(pos.x-34)+'px';gardener.style.top=(pos.y+35)+'px';gardener.classList.add('walking');gardener.querySelector('.gardener-word').textContent=stage===0?'씨앗 심는 중':stage===1?'쑥쑥 자라라!':stage===4?'바구니로 쏙!':'잘 자라고 있네';clearTimeout(window.gardenerTimer);window.gardenerTimer=setTimeout(()=>gardener.classList.remove('walking'),750);if(stage===0){for(let i=0;i<6;i++)addParticle(pos.x-35+i*13,pos.y-100,'•',Math.sin(i)*20,90+i%2*15,650+i*70,'seed')}if(stage===1){for(let i=0;i<18;i++)addParticle(pos.x+30,pos.y-75,'💧',-75+Math.random()*120,35+Math.random()*75,700+Math.random()*700,'water');b.classList.add('just-watered');setTimeout(()=>b.classList.remove('just-watered'),1300)}if(stage===4){for(let i=0;i<3;i++)addParticle(pos.x-20+i*20,pos.y-10,'🥬',target.x-pos.x+20-i*20,target.y-pos.y+10,850+i*140,'harvest');for(let i=0;i<9;i++)addParticle(pos.x,pos.y,'✦',Math.cos(i)*75,Math.sin(i)*65,650,'burst');setTimeout(()=>{$('.farm-basket').classList.add('basket-bounce');setTimeout(()=>$('.farm-basket').classList.remove('basket-bounce'),450)},900)}}
// Capture the previous crop state before the existing handler changes inventory.
$('#plots').addEventListener('click',e=>{const b=e.target.closest('[data-plot]');if(!b||b.disabled||state.job===null)return;animateAction(b,plotStage(ensureFarm().plots[Number(b.dataset.plot)]))},true);
const priorUpdatePlots=updatePlots;updatePlots=function(){priorUpdatePlots();gardenCanvases()};
function animationFrame(now){requestAnimationFrame(animationFrame);if(document.hidden||!farmView||now-lastFrame<32)return;lastFrame=now;gardenCanvases();ensureFarm().plots.forEach((p,i)=>{const c=$(`[data-plot="${i}"] canvas`);if(c)drawPlot(c,p,i,now)});for(let i=particles.length-1;i>=0;i--){const p=particles[i],t=Math.min(1,(now-p.born)/p.duration);if(t>=1){p.el.remove();particles.splice(i,1);continue}const x=p.x+p.dx*t,y=p.y+p.dy*t-(p.kind==='harvest'?Math.sin(t*Math.PI)*100:p.kind==='burst'?Math.sin(t*Math.PI)*25:0);p.el.style.transform=`translate(${x}px,${y}px) rotate(${p.kind==='harvest'?t*160:0}deg) scale(${p.kind==='harvest'?1-t*.5:1})`;p.el.style.opacity=p.kind==='harvest'?'1':String(1-t*.6)}}
gardenCanvases();requestAnimationFrame(animationFrame);

